using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Reflection;using System.Windows.Forms;using Frociart;
internal static class CSharpUiTests {
 static int checks;static void Check(bool value,string text){checks++;if(!value)throw new Exception(text);}
 static void Pump(int ms){var time=System.Diagnostics.Stopwatch.StartNew();while(time.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(3);}}
 static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(o);}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string root=args[0];UiMotion.SetEnabled(true);var doc=FlowPseudocode.Decode("FUNZIONE saluta(x: INTERO) -> TESTO risultato\nSE x > 0 ALLORA\nrisultato=\"Positivo 🐢\"\nALTRIMENTI\nrisultato=\"Altro\"\nFINE SE\nFINE FUNZIONE\nSTAMPA saluta(3)");string before=Convert.ToBase64String(DiagramIO.EncodeDocument(doc));string function=null,node=null;
  foreach(var target in new[]{FlowSourceTarget.Python,FlowSourceTarget.Java,FlowSourceTarget.CSharp})using(var dialog=new SourceCodeDialog(doc,(f,n)=>{function=f;node=n;},target)){
   dialog.Show();Pump(250);Check(dialog.Source!=null&&dialog.Source.Language==target.Id&&dialog.Text.Contains(target.Name),"Native source opens correct target");Check(dialog.Editor.ReadOnly&&dialog.Editor.ShortcutsEnabled&&dialog.Save.Text.Contains("."+target.Extension),"Readable/selectable source and correct extension");Check(dialog.Editor.Text.Replace("\r\n","\n")==SourceCodeDialog.ProgramText(dialog.Source),"Program-only preview is exact");string copied=null;dialog.ClipboardWrite=v=>copied=v;dialog.Copy.PerformClick();Check(copied==dialog.Source.Text,"Copy always includes complete runnable source");dialog.ClipboardWrite=v=>{throw new System.Runtime.InteropServices.ExternalException("Controlled clipboard contention");};dialog.Copy.PerformClick();Check(((Label)Get(dialog,"status")).Text.Contains("Appunti occupati"),"Clipboard failure keeps source available");dialog.Support.Checked=true;Pump(250);Check(dialog.Editor.Text.Replace("\r\n","\n")==dialog.Source.Text,"Support toggle reveals runtime");dialog.Support.Checked=false;Pump(250);Check(!dialog.Editor.Text.Contains("sealed class _fc_Runtime"),"Support code remains hidden in concise view");
   if(target==FlowSourceTarget.CSharp){foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark,false);Pump(250);using(var image=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(root,"csharp-pc-"+(dark?"dark":"light")+".png"));}Check(dialog.Copy.Visible&&dialog.Locate.Visible,"Themed C# controls visible");}string file=Path.Combine(root,"native-source.cs");SourceCodeDialog.WriteSource(file,dialog.Source.Text);Check(File.ReadAllText(file)==dialog.Source.Text,"Real UTF-8 source save");var block=doc.Functions[0].Body.Nodes.First(n=>n.Kind==NodeKind.Process);var line=dialog.Source.ForBlock(doc.Functions[0].Id,block.Id).First();dialog.Editor.Select(dialog.Editor.GetFirstCharIndexFromLine(line.Number-1),0);var origin=dialog.SelectedOrigin();Check(origin!=null&&origin.NodeId==block.Id&&origin.FunctionId==doc.Functions[0].Id,"UTF-16 caret maps to actual function block");dialog.LocateSelection();Check(function==doc.Functions[0].Id&&node==block.Id,"Locate action reaches correct origin");}else dialog.Close();
  }
  Check(Convert.ToBase64String(DiagramIO.EncodeDocument(doc))==before,"All source viewers preserve project");var program=FlowSource.Compile(doc);foreach(string name in new[]{"class","Value","System","Console","_fc_Scope0","X { throw; }","","record"}){bool rejected=false;try{FlowCSharp.Generate(program,"runtime",name);}catch(ArgumentException){rejected=true;}Check(rejected,"Unsafe/conflicting class name rejected: "+name);}
  var broken=DiagramIO.CreateBlank();broken.Edges.Clear();using(var invalid=new SourceCodeDialog(broken,null,FlowSourceTarget.CSharp)){invalid.Show();Pump(150);Check(invalid.Source==null&&!invalid.Save.Enabled&&!invalid.Copy.Enabled&&!invalid.Support.Enabled,"Invalid graph gives diagnostics without stale export");invalid.Close();}
  UiMotion.SetEnabled(false);using(var reduced=new SourceCodeDialog(doc,null,FlowSourceTarget.CSharp)){reduced.Show();reduced.Support.Checked=true;reduced.Support.Checked=false;Check(reduced.Source!=null&&reduced.Editor.Text.Length>0,"Reduced motion retains complete source actions");reduced.Close();}
  Console.WriteLine("CSHARP_PC_UI PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
